import * as React from "react";
import axios from "axios";
import MainLayout from "../layouts/MainLayout";
import { GlobalProvider } from "../components/context/GlobalContext";
import { navigate } from "gatsby"

export default function Test() {
  const [products, setProducts] = React.useState([]);
  const [page, setPage] = React.useState(1);
  const [totalPages, setTotalPages] = React.useState(1);
  const [loading, setLoading] = React.useState(false);
  const [error, setError] = React.useState(null);
  const [cart, setCart] = React.useState(() => {
    const stored =  typeof window !== "undefined" ? localStorage.getItem("test_cart") : null;
    return stored ? JSON.parse(stored) : [];
  });

  const fetchProducts = async (pageNumber) => {
    setLoading(true);
    setError(null);
    try {
      const res = await axios.get(
        `https://cms.magicschoolsupplies.com/wp-json/wp/v2/api`,
        {
          params: {
            type: "products",
            format: "element",
            page: pageNumber,
            per_page: 10,
            status: "private",
          },
        }
      );

      const products = Array.isArray(res.data.products) ? res.data.products : [];
      const totalPages = res.data?.pagination?.pages || 1;

      setProducts(products);
      setTotalPages(totalPages);
      setPage(pageNumber);
    } catch (err) {
      console.error("Failed to fetch products:", err);
      setError("Something went wrong while loading products.");
      setProducts([]);
    }
    setLoading(false);
  };

  React.useEffect(() => {
    fetchProducts(1);
  }, []);

  React.useEffect(() => {
    localStorage.setItem("test_cart", JSON.stringify(cart));
  }, [cart]);

const addToCart = (product) => {
  if (!cart.some((item) => item.id === product.id)) {
    setCart((prev) => [...prev, product]);
  }
};


  const clearCart = () => {
    setCart([]);
  };

  const handlePageChange = (pageNum) => {
    if (pageNum !== page) {
      fetchProducts(pageNum);
    }
  };

  const handlePrev = () => {
    if (page > 1) fetchProducts(page - 1);
  };

  const handleNext = () => {
    if (page < totalPages) fetchProducts(page + 1);
  };

  const renderElements = (elements) => {
    if (!Array.isArray(elements) || elements.length === 0) return null;

    const output = [];
    let currentList = null;

    elements.forEach((el, i) => {
      const key = `${el.element}-${i}`;

      if (el.element === "p") {
        output.push(<p key={key}>{el.value}</p>);
        currentList = null;
      } else if (el.element === "ul") {
        const listItems = el.value
          .split("\n")
          .filter(Boolean)
          .map((v, j) => <li key={`ul-${i}-${j}`}>{v.trim()}</li>);
        output.push(<ul key={key}>{listItems}</ul>);
        currentList = null;
      } else if (el.element === "li") {
        if (!currentList) {
          currentList = [];
          output.push(<ul key={`liwrap-${i}`}>{currentList}</ul>);
        }
        currentList.push(<li key={key}>{el.value}</li>);
      } else if (el.element === "img") {
        output.push(
          <img
            key={key}
            src={el.src}
            alt=""
            srcSet={el.srcset || undefined}
            style={{ maxWidth: 120, margin: "8px 0", display: "block" }}
          />
        );
        currentList = null;
      } else {
        output.push(<p key={key}>{el.value}</p>);
        currentList = null;
      }
    });

    return output;
  };

  const renderPagination = () => {
    const buttons = [];

    for (let i = 1; i <= totalPages; i++) {
      if (i === 1 || i === totalPages || Math.abs(i - page) <= 2) {
        buttons.push(
          <button
            key={i}
            onClick={() => handlePageChange(i)}
            style={{
              margin: "0 4px",
              padding: "6px 12px",
              borderRadius: 4,
              border: i === page ? "2px solid #0070f3" : "1px solid #ccc",
              backgroundColor: i === page ? "#e6f0ff" : "#fff",
              fontWeight: i === page ? "bold" : "normal",
              cursor: i === page ? "default" : "pointer",
            }}
            disabled={i === page}
          >
            {i}
          </button>
        );
      } else if (
        (i === 2 && page > 4) ||
        (i === totalPages - 1 && page < totalPages - 3)
      ) {
        buttons.push(
          <span key={`dots-${i}`} style={{ margin: "0 6px" }}>
            ...
          </span>
        );
      }
    }

    return <div style={{ marginBottom: 20 }}>{buttons}</div>;
  };

  return (
    <GlobalProvider>
      <MainLayout>
                <div style={{ width : '100%', height : 50 }}>  <button onClick={async () => {
                    navigate('/test-cart');
            }} style={{ background: "#0070f3", color: "#fff", padding: 10, border: "none", marginBottom: 6, cursor: "pointer", borderRadius: 4 }}>
           TO CART
            </button> </div>
        <div style={{
          backgroundColor: "#f9f9f9",
          padding: "10px 20px",
          position: "sticky",
          top: 0,
          zIndex: 1000,
          borderBottom: "1px solid #ddd",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center"
        }}>
          <div><strong>🛒 Test Cart:</strong> {cart.length} item{cart.length !== 1 ? "s" : ""}</div>
          <button onClick={clearCart} style={{
            background: "transparent",
            border: "none",
            color: "#0070f3",
            textDecoration: "underline",
            cursor: "pointer"
          }}>
            Clear Test Cart
          </button>
        </div>

        <div style={{ height: "auto", width: "100%", padding: 20 }}>
          <h2>Product List (Page {page})</h2>

          <div style={{ display: "flex", gap: 12, marginBottom: 12 }}>
            <button
              onClick={handlePrev}
              disabled={page <= 1}
              style={{
                padding: "6px 14px",
                borderRadius: 4,
                backgroundColor: "#0070f3",
                color: "#fff",
                border: "none",
                cursor: page <= 1 ? "not-allowed" : "pointer",
              }}
            >
              ◀ Prev
            </button>
            <button
              onClick={handleNext}
              disabled={page >= totalPages}
              style={{
                padding: "6px 14px",
                borderRadius: 4,
                backgroundColor: "#0070f3",
                color: "#fff",
                border: "none",
                cursor: page >= totalPages ? "not-allowed" : "pointer",
              }}
            >
              Next ▶
            </button>
          </div>

          {renderPagination()}

          {loading && (
            <div style={{ display: "flex", justifyContent: "center", padding: "40px 0" }}>
              <div className="custom-spinner" />
              <style>{`
                .custom-spinner {
                  width: 36px;
                  height: 36px;
                  border: 4px solid #ccc;
                  border-top-color: #0070f3;
                  border-radius: 50%;
                  animation: spin 0.8s linear infinite;
                }
                @keyframes spin {
                  to { transform: rotate(360deg); }
                }
              `}</style>
            </div>
          )}

          {error && <p style={{ color: "red" }}>{error}</p>}
          {!loading && !error && products.length === 0 && <p>No products found.</p>}

          {!loading &&
            !error &&
            products.map((prod) => (
              <div
                key={prod?.id || Math.random()}
                style={{
                  marginBottom: 20,
                  borderBottom: "1px solid #ccc",
                  paddingBottom: 10,
                }}
              >
                <h3>{prod?.name || "Unnamed Product"}</h3>

                <div>
                  <strong>Short Description:</strong>
                  {Array.isArray(prod?.short_desc?.elements) &&
                  prod.short_desc.elements.length > 0 ? (
                    renderElements(prod.short_desc.elements)
                  ) : (
                    <p style={{ fontStyle: "italic", color: "#888" }}>
                      No short description.
                    </p>
                  )}
                </div>

                <div>
                  <strong>Long Description:</strong>
                  {Array.isArray(prod?.long_desc?.elements) &&
                  prod.long_desc.elements.length > 0 ? (
                    renderElements(prod.long_desc.elements)
                  ) : (
                    <p style={{ fontStyle: "italic", color: "#888" }}>
                      No long description.
                    </p>
                  )}
                </div>

                <div style={{ marginTop: 10, fontSize: "0.9rem" }}>
                  <div><strong>SKU:</strong> {prod?.sku || "N/A"}</div>
                  <div><strong>Price:</strong> ${prod?.regular_price || "0.00"}</div>
                  {prod?.sale_price && (
                    <div><strong>Sale Price:</strong> ${prod.sale_price}</div>
                  )}
                  <div><strong>Stock Quantity:</strong> {prod?.stock ?? "N/A"}</div>
                  <div><strong>Stock Status:</strong> {prod?.stock_status ?? "N/A"}</div>
                  <div><strong>Weight:</strong> {prod?.weight ?? "N/A"} lbs</div>
                  <div><strong>Dimensions (L×W×H):</strong> {prod?.dimensions?.length ?? "?"}×{prod?.dimensions?.width ?? "?"}×{prod?.dimensions?.height ?? "?"} in</div>
                </div>

                <button
  onClick={() => addToCart(prod)}
  style={{
    marginTop: 10,
    padding: "6px 12px",
    backgroundColor: cart.some((item) => item.id === prod.id) ? "#ccc" : "#28a745",
    color: "#fff",
    border: "none",
    borderRadius: 4,
    cursor: cart.some((item) => item.id === prod.id) ? "not-allowed" : "pointer"
  }}
  disabled={cart.some((item) => item.id === prod.id)}
>
  {cart.some((item) => item.id === prod.id)
    ? "Added to Test Cart"
    : "Add to Test Cart"}
</button>

              </div>
            ))}
        </div>

        <div style={{ width: "100%", height: 50 }} />
      </MainLayout>
    </GlobalProvider>
  );
}
